// Error types mirroring jsonschema's ValidationError / SchemaError surface
// that the translated program relies on.

export class ValidationError {
  constructor(message) {
    this.message = message;
    // Absolute path within the instance (filled in by the validator as the
    // error bubbles up through keyword validators).
    this.path = [];
    // Relative schema path (keyword chain), informational only.
    this.schemaPath = [];
    // Set by the validator loop as the error bubbles up:
    this.validator = undefined;
    this.validatorValue = undefined;
    this.instance = undefined;
    this.schema = undefined;
    // Sub-errors (e.g. for anyOf/oneOf), informational only.
    this.context = [];
  }
}

export class SchemaError extends Error {
  constructor(message, errors = []) {
    super(message);
    this.name = 'SchemaError';
    this.errors = errors;
  }
}

// JSON Schema type checking and Python-flavoured equality helpers.
//
// jsonschema (Python) compares values with Python semantics, where
// True == 1 and False == 0. Its internal `unbool` helper rewrites
// booleans to 1/0 recursively before comparing. We mirror that here.

export function isType(instance, type) {
  switch (type) {
    case 'array':
      return Array.isArray(instance);
    case 'boolean':
      return typeof instance === 'boolean';
    case 'integer':
      return typeof instance === 'number' && Number.isInteger(instance);
    case 'number':
      return typeof instance === 'number';
    case 'null':
      return instance === null;
    case 'object':
      return (
        typeof instance === 'object' && instance !== null && !Array.isArray(instance)
      );
    case 'string':
      return typeof instance === 'string';
    default:
      throw new Error(`Unknown type '${type}'`);
  }
}

// Recursively rewrite true -> 1 and false -> 0 (jsonschema._utils.unbool).
export function unbool(value) {
  if (value === true) return 1;
  if (value === false) return 0;
  if (Array.isArray(value)) return value.map(unbool);
  if (typeof value === 'object' && value !== null) {
    const out = {};
    for (const [k, v] of Object.entries(value)) out[k] = unbool(v);
    return out;
  }
  return value;
}

// Deep equality with Python semantics (after unbool-ing both sides).
export function deepEqual(one, two) {
  return plainEqual(unbool(one), unbool(two));
}

function plainEqual(a, b) {
  if (a === b) return true;
  if (typeof a === 'number' && typeof b === 'number') return a === b;
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!plainEqual(a[i], b[i])) return false;
    }
    return true;
  }
  if (isPlainObject(a) && isPlainObject(b)) {
    const ka = Object.keys(a);
    const kb = Object.keys(b);
    if (ka.length !== kb.length) return false;
    for (const k of ka) {
      if (!Object.prototype.hasOwnProperty.call(b, k)) return false;
      if (!plainEqual(a[k], b[k])) return false;
    }
    return true;
  }
