// ErrorTree: a tree of validation errors keyed by instance path.
// Mirrors jsonschema.exceptions.ErrorTree.
//
// Key semantic: at each tree node, errors are stored in a dict keyed by
// the *validator name*, so multiple errors at the same path produced by
// the same keyword collapse into one entry. `total_errors` therefore can
// be smaller than the number of errors the tree was built from.

export class ErrorTree {
  constructor(errors = []) {
    this.errors = {};
    this._contents = new Map();
    this._instance = undefined;

    for (const error of errors) {
      let container = this;
      for (const element of error.path) {
        container = container._getChild(element);
      }
      container.errors[error.validator] = error;
      container._instance = error.instance;
    }
  }

  _getChild(element) {
    if (!this._contents.has(element)) {
      this._contents.set(element, new ErrorTree());
    }
    return this._contents.get(element);
  }

  get total_errors() {
    let childErrors = 0;
    for (const child of this._contents.values()) {
      childErrors += child.total_errors;
    }
    return Object.keys(this.errors).length + childErrors;
  }
}

// Minimal argparse-compatible CLI parsing for this program.
// Supports: --name value, --name=value, and required arguments.
// On error, prints a usage message to stderr and exits with code 2,
// like Python's argparse.

const PROG = 'test18.mjs';

function usage() {
  return `usage: ${PROG} [-h] --a A --b B`;
}

function fail(message) {
  console.error(usage());
  console.error(`${PROG}: error: ${message}`);
  process.exit(2);
}

// spec: [{ name: 'a', required: true, help: '...' }, ...]
export function parseArgs(argv, spec) {
  const values = {};
  const byName = new Map(spec.map((s) => [s.name, s]));

  for (let i = 0; i < argv.length; i++) {
    let arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      console.log(usage());
      process.exit(0);
    }
    if (!arg.startsWith('--')) {
      fail(`unrecognized arguments: ${arg}`);
    }
    let name;
    let value;
    const eq = arg.indexOf('=');
    if (eq !== -1) {
      name = arg.slice(2, eq);
      value = arg.slice(eq + 1);
    } else {
      name = arg.slice(2);
      if (!byName.has(name)) {
        fail(`unrecognized arguments: ${arg}`);
      }
      i++;
      if (i >= argv.length) {
        fail(`argument --${name}: expected one argument`);
      }
      value = argv[i];
    }
    if (!byName.has(name)) {
      fail(`unrecognized arguments: ${arg}`);
    }
    values[name] = value;
  }

  const missing = spec.filter((s) => s.required && !(s.name in values));
  if (missing.length > 0) {
    const list = missing.map((s) => `--${s.name}`).join(' ');
    fail(`the following arguments are required: ${list}`);
  }
  return values;
}

// Draft7Validator core: keyword dispatch, $ref resolution, descend/evolve
// helpers, is_valid and check_schema.
//
// Keyword implementations live in ./keywords/*.mjs. Each keyword function
// has the signature:
//     (validator, keywordValue, instance, schema) -> iterable<ValidationError>
// Freshly created errors carry an empty `path`; `validator.descend` is used
// to validate subschemas and prepends the path element. The dispatch loop
// below overwrites error.validator with the keyword name at each level as
// errors bubble up, matching jsonschema's behaviour (this is what makes
// ErrorTree collapse same-keyword errors at the same path).

import { ValidationError, SchemaError } from './errors.mjs';
import { isType } from './types.mjs';
import { META_SCHEMA } from './metaSchema.mjs';
import * as core from './keywords/core.mjs';
import * as numeric from './keywords/numeric.mjs';
import * as string from './keywords/string.mjs';
import * as array from './keywords/array.mjs';
import * as object from './keywords/object.mjs';
import * as logical from './keywords/logical.mjs';

const VALIDATORS = {
  // core
  type: core.type,
  enum: core.enum_,
  const: core.const_,
  // numeric
  multipleOf: numeric.multipleOf,
  maximum: numeric.maximum,
  exclusiveMaximum: numeric.exclusiveMaximum,
  minimum: numeric.minimum,
  exclusiveMinimum: numeric.exclusiveMinimum,
  // string
  maxLength: string.maxLength,
  minLength: string.minLength,
  pattern: string.pattern,
  // array
  items: array.items,
  additionalItems: array.additionalItems,
  contains: array.contains,
  maxItems: array.maxItems,
  minItems: array.minItems,
  uniqueItems: array.uniqueItems,
  // object
  properties: object.properties,
  patternProperties: object.patternProperties,
  additionalProperties: object.additionalProperties,
  required: object.required,
  dependencies: object.dependencies,
  propertyNames: object.propertyNames,
  maxProperties: object.maxProperties,
  minProperties: object.minProperties,
  // logical
  allOf: logical.allOf,
  anyOf: logical.anyOf,
  oneOf: logical.oneOf,
  not: logical.not,
  if: logical.if_,
};

export class Draft7Validator {
  static META_SCHEMA = META_SCHEMA;
  static VALIDATORS = VALIDATORS;

  constructor(schema) {
    this.schema = schema;
  }

  isType(instance, type) {
    return isType(instance, type);
  }

  // Resolve a $ref string against the root schema document.
  // Supports "#" and local JSON pointers ("#/definitions/foo").
  resolveRef(ref) {
    if (typeof ref !== 'string' || !ref.startsWith('#')) {
      throw new Error(`Unresolvable reference: ${ref}`);
    }
    const fragment = decodeURIComponent(ref.slice(1));
    if (fragment === '') {
      return this.schema;
    }
    if (!fragment.startsWith('/')) {
      throw new Error(`Unresolvable reference: ${ref}`);
    }
    let target = this.schema;
    for (const rawPart of fragment.slice(1).split('/')) {
      const part = rawPart.replace(/~1/g, '/').replace(/~0/g, '~');
      if (Array.isArray(target)) {
        target = target[Number(part)];
      } else if (target !== null && typeof target === 'object') {
        target = target[part];
      } else {
        throw new Error(`Unresolvable reference: ${ref}`);
      }
      if (target === undefined) {
        throw new Error(`Unresolvable reference: ${ref}`);
      }
    }
    return target;
  }

  *iter_errors(instance) {
    yield* this._iterErrors(instance, this.schema, []);
  }

  *_iterErrors(instance, schema, basePath) {
    if (schema === true) return;
    if (schema === false) {
      const error = new ValidationError(
        `False schema does not allow ${JSON.stringify(instance)}`
      );
      error.path = basePath;
      error.instance = instance;
      error.schema = schema;
      error.validator = false;
      error.validatorValue = false;
      yield error;
      return;
    }
    if (schema === null || typeof schema !== 'object') return;

    // Draft-07 semantics: a $ref replaces its sibling keywords.
    if (typeof schema.$ref === 'string') {
      const resolved = this.resolveRef(schema.$ref);
      yield* this._iterErrors(instance, resolved, basePath);
      return;
    }

    for (const [k, v] of Object.entries(schema)) {
      const fn = VALIDATORS[k];
      if (fn === undefined) continue;
      const errors = fn(this, v, instance, schema);
      if (!errors) continue;
      for (const error of errors) {
        error.validator = k;
        error.validatorValue = v;
        error.instance = instance;
        error.schema = schema;
        error.path = [...basePath, ...error.path];
        error.schemaPath = [k, ...error.schemaPath];
        yield error;
      }
    }
  }

  // Validate `instance` against `subschema`, yielding errors whose paths are
  // prefixed with `pathElement` (pass null/undefined to keep the path).
  *descend(instance, subschema, pathElement) {
    const prefix = pathElement === null || pathElement === undefined ? [] : [pathElement];
    for (const error of this._iterErrors(instance, subschema, prefix)) {
      yield error;
    }
  }

  // True if `instance` is valid against `subschema`.
  isValidAgainst(instance, subschema) {
    return this._iterErrors(instance, subschema, []).next().done;
  }

  is_valid(instance) {
    return this._iterErrors(instance, this.schema, []).next().done;
  }

  // Validates a schema against the Draft-07 meta-schema. Returns nothing
  // (Python returns None); throws SchemaError if the schema is invalid.
  static check_schema(schema) {
    const validator = new Draft7Validator(META_SCHEMA);
    const errors = [...validator._iterErrors(schema, META_SCHEMA, [])];
    if (errors.length > 0) {
      const best = errors[0];
      throw new SchemaError(
        `The schema is invalid: ${best.message}`,
        errors
      );
    }
  }

  check_schema(schema) {
    return Draft7Validator.check_schema(schema);
  }
}

